            pink: FF0099;
        }

        @media (preferscolorscheme: dark) {
            :root {
                text: FFFFFF;
                textsecondary: 999999;
                surface: rgba(0, 0, 0, 0.3);
                border: rgba(255, 255, 255, 0.06);
            }
        }

        body {
            fontfamily: applesystem, systemui, sansserif;
            minheight: 100vh;
            display: flex;
            alignitems: center;
            justifycontent: center;
            overflow: hidden;
            background: FFFFFF;
            color: var(text);
            position: relative;
        }

        @media (preferscolorscheme: dark) {
            body {
                background: 000000;
            }
