        .gradientmesh {
            position: fixed;
            width: 150%;
            height: 150%;
            top: 25%;
            left: 25%;
            zindex: 0;
            opacity: 0.4;
            filter: blur(150px) saturate(150%);
        }

        @media (preferscolorscheme: dark) {
            .gradientmesh {
                opacity: 0.3;
                filter: blur(150px) saturate(100%);
            }
        }

        .gradientmesh::before {
            content: '';
            position: absolute;
            width: 100%;
            height: 100%;
            background: radialgradient(circle at 30% 20%, var(magenta) 0%, transparent 50%),
                        radialgradient(circle at 70% 40%, var(green) 0%, transparent 50%),
                        radialgradient(circle at 50% 80%, var(blue) 0%, transparent 50%);
            animation: breathe 20s easeinout infinite;
        }

        @keyframes breathe {
            0%, 100% { transform: scale(1) rotate(0deg); }
            33% { transform: scale(1.1) rotate(120deg); }
            66% { transform: scale(0.9) rotate(240deg); }
        }

        .sphere {
            position: absolute;
            borderradius: 50%;
            filter: blur(100px);
            opacity: 0.6;
        }

        .sphere1 {
            width: 600px;
            height: 600px;
            background: lineargradient(135deg, var(magenta), var(purple));
            top: 300px;
            left: 300px;
            animation: float1 25s easeinout infinite;
        }

        .sphere2 {
            width: 500px;
            height: 500px;
            background: lineargradient(135deg, var(green), var(blue));
            bottom: 250px;
            right: 250px;
            animation: float2 30s easeinout infinite;
        }

        .sphere3 {
            width: 400px;
            height: 400px;
            background: lineargradient(135deg, var(blue), var(pink));
            top: 50%;
            left: 50%;
            transform: translate(50%, 50%);
            animation: float3 35s easeinout infinite;
        }

        @keyframes float1 {
            0%, 100% { transform: translate(0, 0); }
            50% { transform: translate(100px, 50px); }
