            border: 1px solid var(border);
            boxshadow: 0 20px 40px 20px rgba(0, 0, 0, 0.1);
        }

        @media (preferscolorscheme: dark) {
            .card {
                boxshadow: 0 20px 40px 20px rgba(255, 255, 255, 0.05);
            }
        }

        .logo {
            width: 56px;
            height: 56px;
            margin: 0 auto 2.5rem;
            display: flex;
            alignitems: center;
            justifycontent: center;
            fontsize: 28px;
            fontweight: 700;
            background: lineargradient(135deg, var(magenta), var(blue));
            webkitbackgroundclip: text;
            webkittextfillcolor: transparent;
            backgroundclip: text;
        }

        h1 {
            fontsize: 2rem;
            fontweight: 700;
            textalign: center;
            marginbottom: 0.5rem;
            letterspacing: 0.03em;
        }

        .subtitle {
            textalign: center;
            color: var(textsecondary);
            marginbottom: 3rem;
            fontsize: 1rem;
            fontweight: 400;
        }

        .formgroup {
            marginbottom: 1.75rem;
        }

        label {
            display: block;
            marginbottom: 0.5rem;
            fontsize: 0.875rem;
            fontweight: 500;
            color: var(textsecondary);
        }

        input {
            width: 100%;
            padding: 1.125rem 1.25rem;
            background: transparent;
            border: 1.5px solid var(border);
            borderradius: 16px;
            fontsize: 1rem;
            transition: all 0.2s cubicbezier(0.4, 0, 0.2, 1);
            webkitappearance: none;
        }

        input:focus {
            outline: none;
            bordercolor: var(magenta);
            background: rgba(255, 0, 110, 0.02);
        }

        input::placeholder {
            color: var(textsecondary);
            opacity: 0.6;
        }

        .btn {
            width: 100%;
            padding: 1.125rem;
            background: lineargradient(135deg, var(magenta), var(blue));
            color: white;
            border: none;
            borderradius: 16px;
            fontsize: 1rem;
            fontweight: 600;
            cursor: pointer;
            transition: all 0.2s cubicbezier(0.4, 0, 0.2, 1);
            margintop: 0.5rem;
            position: relative;
            overflow: hidden;
        }

        .btn::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: lineargradient(135deg, var(blue), var(green));
            opacity: 0;
            transition: opacity 0.3s ease;
        }

        .btn:hover::before {
            opacity: 1;
        }

        .btn span {
            position: relative;
            zindex: 1;
        }

        .btn:hover {
            transform: translateY(2px);
            boxshadow: 0 10px 30px 10px rgba(255, 0, 110, 0.4);
        }

        .btn:active {
            transform: translateY(0);
        }

        .divider {
            display: flex;
            alignitems: center;
            margin: 2.5rem 0 2rem;
            color: var(textsecondary);
            fontsize: 0.875rem;
        }

        .divider::before,
        .divider::after {
            content: '';
            flex: 1;
            height: 1px;
            background: lineargradient(90deg, transparent, var(border), transparent);
        }

        .divider span {
            padding: 0 1.25rem;
        }

        .socialgrid {
            display: grid;
            gridtemplatecolumns: repeat(3, 1fr);
            gap: 1rem;
        }

        .socialbtn {
            aspectratio: 1;
