            transform: translate(50%, 50%);
            transition: all 0.3s ease;
        }

        .socialbtn:hover::before {
            width: 100%;
            height: 100%;
        }

        .socialbtn svg {
            width: 22px;
            height: 22px;
            fill: var(text);
            position: relative;
            zindex: 1;
        }

        .progress {
            display: flex;
            justifycontent: center;
            gap: 0.625rem;
            marginbottom: 2.5rem;
        }

        .dot {
            width: 6px;
            height: 6px;
            borderradius: 50%;
            background: var(border);
            transition: all 0.3s cubicbezier(0.4, 0, 0.2, 1);
        }

        .dot.active {
            width: 24px;
            borderradius: 3px;
            background: lineargradient(90deg, var(magenta), var(blue));
        }

        .link {
            textalign: center;
            margintop: 2rem;
            fontsize: 0.875rem;
        }

        .link a {
            color: var(textsecondary);
            textdecoration: none;
            transition: color 0.2s ease;
        }

        .link a:hover {
            color: var(magenta);
