                --text-secondary: #999999;
                --surface: rgba(10, 10, 10, 0.4);
                --border: rgba(255, 255, 255, 0.06);
            }
        }

        *, *::before, *::after {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-main);
            min-height: 100vh;
            display: flex;
            align-items: center;
            justify-content: center;
            overflow: hidden;
            background: #f0f0f0;
            color: var(--text);
            position: relative;
        }

        @media (prefers-color-scheme: dark) {
            body { background: #000000; }
        }

        .gradient-mesh {
            position: fixed;
            width: 150vw;
            height: 150vh;
            top: -25vh;
            left: -25vw;
            z-index: 0;
            --mx: 50%; /* mouse x */
