            filter: blur(150px);
            opacity: 0.5;
            transition: background 0.5s ease-out;
        }

        @media (prefers-color-scheme: dark) {
            .gradient-mesh { opacity: 0.35; }
        }

        @keyframes breathe {
            0% { transform: scale(1); }
            100% { transform: scale(1.2) rotate(30deg); }
