        .form-step { display: none; }
        .form-step.active { display: block; animation: fadeIn 0.5s ease; }
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

        .form-group {
            position: relative;
            margin-bottom: 1.75rem;
        }

        label {
            position: absolute;
            top: 1rem;
            left: 1.25rem;
            font-size: 1rem;
            color: var(--text-secondary);
            pointer-events: none;
            transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
            font-weight: 500;
            background-color: var(--label-bg);
            padding: 0 0.25rem;
        }

        input {
            width: 100%;
            padding: 1rem 1.25rem;
            background: transparent;
            border: 1.5px solid var(--border);
            border-radius: 16px;
            font-size: 1rem;
            color: var(--text);
            font-family: var(--font-main);
            transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
        }

        input:focus {
            outline: none;
            border-color: var(--magenta);
            background: rgba(255, 0, 110, 0.03);
        }

        input:focus + label,
        input:not(:placeholder-shown) + label {
            top: -0.6rem;
            left: 1rem;
            font-size: 0.75rem;
            font-weight: 600;
            color: var(--magenta);
            /* This is a trick to make the label "cut out" the border */
            @media (prefers-color-scheme: light) { --label-bg: #fff; }
            @media (prefers-color-scheme: dark) { --label-bg: #111; }
        }

        .btn {
            width: 100%;
            padding: 1.125rem;
            background: linear-gradient(135deg, var(--magenta), var(--blue));
            color: white;
            border: none;
            border-radius: 16px;
            font-size: 1rem;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
            margin-top: 0.5rem;
            position: relative;
            overflow: hidden;
            transform: translateZ(20px); /* 3D effect */
        }

        .btn span { position: relative; z-index: 2; }
        .btn canvas { position: absolute; top: 0; left: 0; width: 100%; height: 100%; z-index: 1; }

        .btn:hover {
            transform: translateY(-3px) translateZ(25px) scale(1.02);
            box-shadow: 0 12px 30px -10px rgba(255, 0, 110, 0.5);
        }
        .btn:active { transform: translateY(0) translateZ(20px) scale(1); }

        .divider {
            display: flex; align-items: center; margin: 2rem 0; color: var(--text-secondary); font-size: 0.875rem;
        }
        .divider::before, .divider::after { content: ''; flex: 1; height: 1px; background: var(--border); }
        .divider span { padding: 0 1.25rem; }

        .social-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
        .social-btn {
            aspect-ratio: 1; background: transparent; border: 1.5px solid var(--border); border-radius: 16px;
            cursor: pointer; display: flex; align-items: center; justify-content: center;
            transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
        }
        .social-btn:hover { border-color: var(--text-secondary); transform: translateY(-3px); }
        .social-btn svg { width: 24px; height: 24px; fill: var(--text); }

        .progress { display: flex; justify-content: center; gap: 0.625rem; margin-bottom: 2rem; }
        .dot {
            width: 8px; height: 8px; border-radius: 50%; background: var(--border);
            transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
        }
        .dot.active {
            width: 28px; border-radius: 4px; background: linear-gradient(90deg, var(--magenta), var(--blue));
        }

        .success-message { text-align: center; }
        .success-icon { font-size: 3rem; margin-bottom: 1rem; }

        @media (prefers-reduced-motion: reduce) {
            .gradient-mesh, .card { animation: none; transition: none; }
        }
    </style>
</head>
<body>
    <div class="gradient-mesh"></div>

    <div class="container">
        <div class="card">
            <div class="logo">C</div>

            <div class="progress">
