            <form id="connectForm">
                <!-- Step 1: Login -->
                <div class="form-step active" data-step="1">
                    <h1>Üdvözöljük!</h1>
                    <p class="subtitle">Jelentkezzen be a folytatáshoz</p>

                    <div class="form-group">
