<script>
document.addEventListener('DOMContentLoaded', () => {
    const card = document.querySelector('.card');
    const gradientMesh = document.querySelector('.gradient-mesh');
    const form = document.getElementById('connectForm');
    const steps = document.querySelectorAll('.form-step');
    const dots = document.querySelectorAll('.progress .dot');

    let currentStep = 1;

    // --- 1. 3D Card & Gradient Follow Mouse ---
    document.body.addEventListener('mousemove', (e) => {
        const { clientX, clientY, currentTarget } = e;
        const { clientWidth, clientHeight } = currentTarget;

        const x = (clientX / clientWidth) - 0.5;
        const y = (clientY / clientHeight) - 0.5;

        // Card tilt effect
        const rotateX = -y * 15; // Max 15deg rotation
        const rotateY = x * 15;
        card.style.transform = `rotateX(${rotateX}deg) rotateY(${rotateY}deg)`;

        // Gradient mesh follow
        gradientMesh.style.setProperty('--mx', `${clientX}px`);
        gradientMesh.style.setProperty('--my', `${clientY}px`);
    });

    // Reset on mouse leave
    document.body.addEventListener('mouseleave', () => {
        card.style.transform = 'rotateX(0deg) rotateY(0deg)';
    });


    // --- 2. Form Stepping Logic ---
    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const currentStepElement = form.querySelector(`.form-step.active`);
        const inputs = currentStepElement.querySelectorAll('input[required]');
        let isValid = true;
        inputs.forEach(input => {
            if (!input.value) {
                isValid = false;
                // You can add error styling here
            }
        });

        if (isValid && currentStep < 3) {
            // Particle effect on the clicked button
            const button = currentStepElement.querySelector('.btn');
            if (button) createParticles(button.querySelector('canvas'));

            setTimeout(() => {
                currentStep++;
                updateFormStep();
            }, 300); // Wait for particle animation to start
        }
    });

    function updateFormStep() {
        steps.forEach(step => step.classList.remove('active'));
        document.querySelector(`.form-step[data-step="${currentStep}"]`).classList.add('active');

        dots.forEach((dot, index) => {
            if (index < currentStep) {
                dot.classList.add('active');
            } else {
                dot.classList.remove('active');
            }
            // Make last dot simple circle
            if (index === 2 && currentStep > 2) {
                dot.style.width = '8px';
            }
        });
    }

    // --- 3. Button Particle Effect ---
    function createParticles(canvas) {
        const ctx = canvas.getContext('2d');
        canvas.width = canvas.offsetWidth;
        canvas.height = canvas.offsetHeight;
        let particles = [];
        const particleCount = 20;

        for (let i = 0; i < particleCount; i++) {
            particles.push({
                x: canvas.width / 2,
                y: canvas.height / 2,
                vx: (Math.random() - 0.5) * 4,
                vy: (Math.random() - 0.5) * 4,
                size: Math.random() * 3 + 1,
                alpha: 1,
                color: `hsl(${Math.random() * 60 + 290}, 100%, 70%)` // Pinks and purples
            });
        }

        function animateParticles() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            particles.forEach(p => {
                p.x += p.vx;
                p.y += p.vy;
                p.alpha -= 0.03;

                if (p.alpha > 0) {
                    ctx.globalAlpha = p.alpha;
                    ctx.fillStyle = p.color;
                    ctx.beginPath();
                    ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
                    ctx.fill();
                }
            });

            particles = particles.filter(p => p.alpha > 0);

            if (particles.length > 0) {
                requestAnimationFrame(animateParticles);
            } else {
                 ctx.clearRect(0, 0, canvas.width, canvas.height);
            }
        }
        requestAnimationFrame(animateParticles);
    }
});
</script>

</body>
